style.css:
@-moz-document domain("www.xiaoqiqiao.com") {
/* 文字样式设置区域 */
    /* 对目标元素及其内部文本节点所在元素设置文字样式 */
   .app_examPage_left_option_minH *:not(script):not(style):not(link):not(meta):not(title):not([contenteditable="true"]):not([role="presentation"]):not([aria-hidden="true"]){
        color: #000000!important; /* 设置文字颜色为黑色，保证文字清晰可见且颜色统一 */
        font-weight: normal!important; /* 设置文字为常规粗细 */
        font-family: "黑体"!important; /* 设置字体为黑体 */
        letter-spacing: 1.5px!important; /* 设置文字间隔为1.5像素 */
        line-height: 1.5px!important; /* 设置行间距为1.5倍，以字体大小为基准的1.5倍 */
        background-color: #ffffff!important; /* 设置背景颜色为纯白，营造简洁干净的视觉背景 */
    }

    /* 元素隐藏区域 */
    /* 隐藏<span class="ant-radio"><input type="radio" class="ant-radio-input" value="A"><span class="ant-radio-inner"></span></span>结构中的特定span元素 */
    span.ant-radio span.ant-radio-inner {
        display: none!important;
    }

    /* 隐藏<span class="ant-checkbox"><input type="checkbox" class="ant-checkbox-input" value="A"><span class="ant-checkbox-inner"></span></span>结构中的特定span元素 */
    span.ant-checkbox input[type="checkbox"].ant-checkbox-input + span.ant-checkbox-inner {
        display: none!important;
    }
}
